import json
import re
try:
    vars['route'] = 'dialogue'
    vars['commit_permission'] = ''
    stage = str(vars.get('stage','select'))
    old_stage = stage
    event = str(vars.get('event') or 'unclear')
    cards = json.loads(vars.get('cards_json','[]'))
    name = str(vars.get('answer_name') or '').strip()
    digits = re.sub(r'[^0-9]', '', str(vars.get('answer_digits') or ''))
    week = int(vars.get('answer_week') or 0)
    currency = str(vars.get('answer_currency') or '')
    focus = str(vars.get('answer_focus') or '')
    if focus: vars['focus'] = focus
    if currency: vars['selected_currency'] = currency
    def question():
        names = list(dict.fromkeys(c.get('productName','') for c in cards if c.get('productName')))[:2]
        return 'Hangi kartınızın borcunu öğrenmek istersiniz?' + (' Örneğin, ' + ' veya '.join(names) + ' diyebilirsiniz.' if names else ' Kartınızın son dört hanesini söyler misiniz?')
    def fail(text):
        vars['failed'] = int(vars.get('failed',0)) + 1
        vars['utterance'] = text
        if vars['failed'] >= 3: vars['route'] = 'tries_end'
    def email_prompt():
        if not vars.get('registered_email'):
            vars['utterance'] = 'Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.'
            vars['stage'] = 'finish'
        elif not vars.get('issued_statement_date'):
            vars['utterance'] = 'Kartınızın henüz kesilmiş bir ekstresi olmadığı için gönderebileceğim bir ekstre bulunmuyor.'
            vars['stage'] = 'finish'
        else:
            available = json.loads(vars.get('available_currencies_json','[]'))
            if vars.get('selected_currency') not in available:
                if len(available) == 1: vars['selected_currency'] = available[0]
                else:
                    labels = dict(TL='Türk Lirası',USD='Dolar',EUR='Euro',GBP='İngiliz Sterlini')
                    vars['stage'] = 'email_currency'
                    vars['utterance'] = 'Hangi para birimine ait ekstrenizi göndermemi istersiniz? ' + ', '.join(labels[x] for x in available) + '.'
                    return
            vars['stage'] = 'email_confirm'
            vars['utterance'] = 'Ekstrenizi ' + str(vars.get('spoken_email') or vars['registered_email']) + ' adresine göndermemi ister misiniz?'
            vars['email_binding'] = '|'.join(str(vars.get(k,'')) for k in ['selected_card_number','issued_statement_date','registered_email','selected_currency'])
    if event != 'silence': vars['silences'] = 0
    if event == 'agent': vars['route'] = 'agent_end'
    elif event == 'pay': vars['route'] = 'payment_end'
    elif event == 'dispute': vars['route'] = 'dispute_end'
    elif event == 'third_party': vars['route'] = 'login_end'
    elif event == 'non_turkish': vars['route'] = 'language_end'
    elif event == 'switch_transaction' or event == 'done': vars['route'] = 'main_end'
    elif event == 'silence':
        vars['silences'] = int(vars.get('silences',0)) + 1
        if vars['silences'] >= 3: vars['route'] = 'silence_end'
        else: vars['utterance'] = 'Hangi kartınız?' if stage == 'select' else ('Onaylıyor musunuz?' if stage in ['week_confirm','email_confirm'] else 'Tercihinizi söyler misiniz?')
    elif event == 'repeat': pass
    elif event == 'secret':
        vars['utterance'] = 'Bankamız sizden şifre veya tek kullanımlık kod istemez. Lütfen bu bilgileri paylaşmayın. ' + str(vars.get('utterance',''))
    elif event == 'private_data':
        vars['utterance'] = 'Bu bilgileri paylaşamam. Kartınızın yalnız son dört hanesini kullanabilirim. ' + str(vars.get('utterance',''))
    elif event == 'complaint':
        count = int(vars.get('calming',0))
        if count >= 3: vars['route'] = 'agent_end'
        else:
            vars['calming'] = count + 1
            vars['utterance'] = 'Sizi anlıyorum; size yardımcı olmak istiyorum. ' + str(vars.get('utterance',''))
    elif event == 'out_of_scope':
        if stage != 'out_of_scope':
            vars['resume_stage'] = stage
            vars['resume_utterance'] = vars.get('utterance','')
        vars['stage'] = 'out_of_scope'
        vars['utterance'] = 'Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?'
    elif stage == 'out_of_scope':
        if event == 'yes': vars['route'] = 'main_end'
        elif event == 'no':
            vars['stage'] = vars['resume_stage']
            vars['utterance'] = vars['resume_utterance']
        else: fail('Sizi ana menüye aktarmamı ister misiniz?')
    elif event == 'other_card' and stage != 'select':
        vars['stage'] = 'select'
        vars['selection_mode'] = 'name'
        vars['candidates_json'] = json.dumps(cards)
        vars['preview_binding'] = ''
        vars['selected_currency'] = currency
        vars['utterance'] = question()
    elif stage == 'select':
        if event == 'email': vars['pending'] = 'email'
        if event == 'all_cards':
            fail('Borç bilgilerini bir kart için sorgulayabilirim. ' + question())
        elif event == 'no': vars['route'] = 'main_end'
        else:
            mode = vars.get('selection_mode','name')
            candidates = json.loads(vars.get('candidates_json',vars['cards_json']))
            if name:
                norm = name.casefold()
                exact = [c for c in cards if str(c.get('productName','')).casefold() == norm]
                candidates = exact or [c for c in cards if norm in str(c.get('productName','')).casefold()]
                mode = 'name'
            if digits:
                length = len(digits)
                if length == 4:
                    candidates = [c for c in candidates if c.get('cardNumberLast4') == digits]
                elif length in [6,16,19] and mode in ['six','full']:
                    matches = []
                    unknown = []
                    for c in candidates:
                        number = str(c['cardNumber'])
                        tail = number[-length:] if length == 6 else number
                        if len(tail) != length: continue
                        if all(not x.isdigit() or x == y for x,y in zip(tail,digits)):
                            if tail.isdigit(): matches.append(c)
                            else: unknown.append(c)
                    candidates = matches if not unknown else matches + unknown
                    if unknown:
                        fail('Servisten gelen maskeli kart bilgisiyle bu kartları güvenli şekilde ayırt edemiyorum. Başka bir kart adı seçebilir misiniz?')
                        vars['selection_mode'] = 'name'
                        vars['candidates_json'] = json.dumps(cards)
                        candidates = []
                        mode = 'masked_unresolved'
                else:
                    candidates = []
            if len(candidates) == 1:
                c = candidates[0]
                vars['selected_card_number'] = c['cardNumber']
                vars['selected_last4'] = c['cardNumberLast4']
                vars['selected_name'] = c.get('productName','')
                vars['preview_binding'] = ''
                vars['selected_currency'] = currency
                vars['route'] = 'balance'
            elif len(candidates) > 1:
                vars['candidates_json'] = json.dumps(candidates)
                digit_words = ['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
                if digits and len(digits) == 4:
                    vars['selection_mode'] = 'six'
                    vars['utterance'] = 'Son dört hanesi ' + ' '.join(digit_words[int(x)] for x in digits) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
                elif digits and len(digits) == 6 and mode != 'masked_unresolved':
                    vars['selection_mode'] = 'full'
                    vars['utterance'] = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
                elif name:
                    vars['selection_mode'] = 'four'
                    names = list(dict.fromkeys(c.get('productName','') for c in candidates))
                    vars['utterance'] = names[0] + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?' if len(names) == 1 else 'Bu tanıma uyan kartlarınız: ' + ', '.join(names) + '. Hangisini tercih edersiniz?'
                else: fail(question())
            elif mode != 'masked_unresolved':
                vars['candidates_json'] = json.dumps(cards)
                vars['selection_mode'] = 'name'
                fail('Bu bilgilerle eşleşen uygun bir kartınız bulunmuyor. ' + question())
    elif stage == 'another':
        if event == 'yes':
            vars['stage'] = 'select'
            vars['selection_mode'] = 'name'
            vars['candidates_json'] = json.dumps(cards)
            vars['utterance'] = question()
        elif event == 'no':
            if vars.get('balance_mode') in ['new','clear']: vars['route'] = 'main_end'
            else:
                vars['reading_pending'] = ''
                vars['route'] = 'email_lookup'
        elif event == 'email':
            vars['pending'] = 'email'
            vars['reading_pending'] = ''
            vars['route'] = 'email_lookup'
        elif event == 'week': vars['route'] = 'week_lookup'
        else: fail('Başka bir kartınızın borcunu öğrenmek ister misiniz?')
    elif event == 'email' and stage not in ['email_confirm','email_currency']:
        if int(vars.get('send_count',0)) >= 3: vars['route'] = 'main_end'
        else:
            vars['pending'] = 'email'
            vars['reading_pending'] = ''
            vars['route'] = 'email_lookup'
    elif event == 'week' and stage not in ['week_start','week_choice','week_confirm']:
        changed = json.loads(vars.get('week_changed_json','[]'))
        attempted = json.loads(vars.get('week_attempted_json','[]'))
        if vars.get('selected_card_number') in changed:
            vars['utterance'] = 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Bu çağrıda değişiklik yapıldı; geri alamıyorum.'
            vars['stage'] = 'finish'
        elif vars.get('selected_card_number') in attempted: vars['route'] = 'week_error'
        else: vars['route'] = 'week_lookup'
    elif stage == 'offer':
        if event == 'no': vars['route'] = 'main_end'
        elif event == 'interrupt':
            vars['utterance'] = 'Ekstrenizi kayıtlı mail adresinize gönderebilirim.' if vars.get('registered_email') else 'Başka bir işlem istemiyorsanız sizi ana menüye yönlendirebilirim.'
        else: fail('Ekstrenizi kayıtlı e-posta adresinize göndermemi ister misiniz?' if vars.get('registered_email') else 'Ana menüye dönmek ister misiniz?')
        if event == 'yes':
            if vars.get('registered_email'): email_prompt()
            else: vars['route'] = 'main_end'
    elif stage == 'email_currency':
        available = json.loads(vars.get('available_currencies_json','[]'))
        if currency in available: email_prompt()
        elif event == 'no': vars['route'] = 'main_end'
        else: fail(str(vars.get('utterance','Hangi para biriminin ekstresini istersiniz?')))
    elif stage == 'email_confirm':
        if event == 'yes':
            binding = '|'.join(str(vars.get(k,'')) for k in ['selected_card_number','issued_statement_date','registered_email','selected_currency'])
            if binding == vars.get('email_binding') and vars.get('registered_email') and int(vars.get('send_count',0)) < 3:
                vars['commit_permission'] = 'email'
                vars['route'] = 'email_commit'
            else: vars['route'] = 'service_error'
        elif event == 'no': vars['route'] = 'main_end'
        elif event == 'email':
            vars['utterance'] = 'Yalnız en son kesilmiş ekstrenizi bankamızda kayıtlı e-posta adresinize gönderebilirim. Ekstrenizi ' + vars['spoken_email'] + ' adresine göndermemi ister misiniz?'
        else: fail('Ekstrenizi kayıtlı adresinize göndermemi istiyorsanız açıkça evet der misiniz?')
    elif stage == 'week_start':
        if event == 'no': vars['route'] = 'main_end'
        elif event in ['yes','week','answer']:
            vars['stage'] = 'week_choice'
            vars['utterance'] = 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ' + vars['options_text']
        else: fail('Hesap kesim tarihinizi değiştirmek ister misiniz?')
    elif stage == 'week_choice':
        if event == 'no': vars['route'] = 'main_end'
        elif week == int(vars['current_statement_week']):
            vars['utterance'] = 'Kartınız zaten bu hesap kesim haftasında; değişiklik gerekmiyor.'
            vars['stage'] = 'finish'
        elif week in [1,2,3,4]:
            vars['selected_statement_week'] = week
            vars['preview_binding'] = ''
            vars['route'] = 'week_preview'
        else: fail(vars['options_text'])
    elif stage == 'week_confirm':
        if event == 'no': vars['route'] = 'main_end'
        elif week and week != int(vars['selected_statement_week']):
            vars['preview_binding'] = ''
            vars['stage'] = 'week_choice'
            vars['utterance'] = vars['options_text']
        elif event == 'yes':
            binding = vars['selected_card_number'] + ':' + str(vars['selected_statement_week'])
            if binding == vars.get('preview_binding') and vars.get('preview_date') and vars.get('preview_due'):
                vars['commit_permission'] = 'week'
                vars['route'] = 'week_commit'
            else: vars['route'] = 'week_error'
        else: fail('Bu değişikliği onaylıyorsanız açıkça evet der misiniz?')
    elif stage == 'finish': vars['route'] = 'main_end'
    else: fail('Tercihinizi açıkça söyler misiniz?')
    if vars.get('stage') != old_stage:
        vars['failed'] = 0
        vars['silences'] = 0
    vars['event'] = ''
    vars['answer_name'] = ''
    vars['answer_digits'] = ''
    vars['answer_week'] = 0
    vars['answer_currency'] = ''
    vars['answer_focus'] = ''
except Exception:
    vars['route'] = 'service_error'
    vars['commit_permission'] = ''
    vars['utterance'] = ''

function.description:
Request:

```json
{
  "data": { "customerNo": "90000001", "aiFlow": "CardOps" },
  "call": { "ani": "<caller's number>", "lang": "tr" }
}
```

`customerNo` may be sent as a string or as a number, both are accepted. `aiFlow` tells us which use case is asking; for this one it's `"CardOps"` (not validated in test).

Response, one card:

```json
{
  "data": {
    "cards": [
      {
        "cardNumber": "540000******1234",
        "cardNumberLast4": "1234",
        "productName": "Yıldız Pratik Classic",
        "status": "A",
        "isMainCard": true
      }
    ],
    "validCardsCount": 1,
    "exitState": "1_CARD"
  },
  "result": { "returnCode": "1", "...": "as in section 3" }
}
```

Response, several cards (abridged):

```json
{
  "data": {
    "cards": [
      { "cardNumber": "540000******4253", "cardNumberLast4": "4253", "productName": "Yıldız Pratik", "status": "A", "isMainCard": true },
      { "cardNumber": "545000******4253", "cardNumberLast4": "4253", "productName": "Yıldız Pratik", "status": "A", "isMainCard": true },
      { "cardNumber": "540000******6184", "cardNumberLast4": "6184", "productName": "Yıldız Pratik", "status": "A", "isMainCard": true },
      { "cardNumber": "540000******8870", "cardNumberLast4": "8870", "productName": "Yıldız Tasarım", "status": "A", "isMainCard": true }
    ],
    "validCardsCount": 4,
    "exitState": "MULTI_CARD"
  },
  "result": { "returnCode": "1", "...": "" }
}
```

- `exitState`: `"1_CARD"` or `"MULTI_CARD"`.
- Only active cards come back (`status` `"A"`). `isMainCard` is `false` for a card that isn't the customer's own main card; it's still in the list.
- Two cards can have the same product name and the same last four digits (see above). Don't assume `cardNumberLast4` is unique.
- `productName` is free text from the card system, whatever was typed in there.
- Masking: in the **test environment** `cardNumber` comes back masked, first 6 and last 4 digits visible (`540000******1234`). What production returns in this field I still have to confirm with the card platform team; build so that it works with the masked form.

Errors: 404 `FB_IVR_CHANNEL_102`, 500 `FBE00099`.

