import json
import datetime
try:
    def number(n):
        n = int(n)
        ones = ['','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
        tens = ['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan']
        def small(x):
            parts = []
            if x >= 100:
                if x // 100 > 1: parts.append(ones[x // 100])
                parts.append('yüz')
            if (x % 100) // 10: parts.append(tens[(x % 100) // 10])
            if x % 10: parts.append(ones[x % 10])
            return ' '.join(parts)
        if n == 0: return 'sıfır'
        if n < 0: return 'eksi ' + number(-n)
        parts = []
        for power, label in [(10**12,'trilyon'),(10**9,'milyar'),(10**6,'milyon'),(1000,'bin')]:
            q, n = divmod(n, power)
            if q:
                parts.append((number(q) + ' ' if q != 1 or label != 'bin' else '') + label)
        if n: parts.append(small(n))
        return ' '.join(parts)
    def money(value, currency):
        text = str(value)
        if 'e' in text.lower(): text = format(value, '.10f').rstrip('0').rstrip('.')
        whole, _, fraction = text.partition('.')
        fraction = fraction.rstrip('0')
        if len(fraction) > 2: raise ValueError('Unsupported precision')
        cents = int((fraction + '00')[:2])
        suffix = 'kuruş' if currency == 'Türk Lirası' else ('peni' if currency == 'İngiliz Sterlini' else 'sent')
        return number(int(whole)) + ' ' + currency + (' ' + number(cents) + ' ' + suffix if cents else '')
    def date_value(s):
        return datetime.datetime.strptime(s, '%d.%m.%Y').date()
    def date_speech(s):
        d = date_value(s)
        months = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
        return str(d.day) + ' ' + months[d.month-1] + ' ' + str(d.year)
    def intro():
        digits = ['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
        last = str(vars['selected_last4'])
        return 'Sonu ' + ' '.join(digits[int(x)] for x in last) + ' ile biten ' + (str(vars.get('selected_name', '')) + ' ' if vars.get('selected_name') else '')
    def selection_prompt(cards):
        names = list(dict.fromkeys(c.get('productName','') for c in cards if c.get('productName')))[:2]
        return 'Hangi kartınızın borcunu öğrenmek istersiniz?' + (' Örneğin, ' + ' veya '.join(names) + ' diyebilirsiniz.' if names else ' Kartınızın son dört hanesini söyler misiniz?')
    vars['route'] = 'service_error'
    op = str(vars.get('operation', ''))
    if op.startswith('statement_week'): vars['route'] = 'week_error'
    envelope = json.loads(vars['builder_result_' + op])
    body = envelope.get('data', dict())
    status = int(envelope.get('status_code', 0))
    code = str(body.get('result', dict()).get('returnCode', ''))
    if op == 'cards_list' and status == 404 and code == 'FB_IVR_CHANNEL_102':
        vars['route'] = 'no_cards'
    else:
        if status != 200 or code != '1' or not isinstance(body.get('data'), dict): raise ValueError('Service failed')
        data = body['data']
        if op == 'cards_list':
            datetime.datetime.fromisoformat(str(vars['now']))
            cards = data['cards']
            if not isinstance(cards, list): raise ValueError('Missing list')
            cards = [c for c in cards if c.get('status') == 'A' and c.get('isMainCard') is True]
            vars['cards_json'] = json.dumps(cards, ensure_ascii=False)
            vars['seen_json'] = '[]'
            vars['week_attempted_json'] = '[]'
            vars['week_changed_json'] = '[]'
            vars['send_count'] = 0
            vars['selected_currency'] = ''
            vars['pending'] = ''
            vars['focus'] = ''
            vars['failed'] = 0
            vars['silences'] = 0
            vars['calming'] = 0
            vars['resume_stage'] = ''
            vars['selection_mode'] = 'name'
            vars['candidates_json'] = json.dumps(cards, ensure_ascii=False)
            if not cards:
                vars['route'] = 'no_cards'
            elif len(cards) == 1:
                c = cards[0]
                vars['selected_card_number'] = c['cardNumber']
                vars['selected_last4'] = c['cardNumberLast4']
                vars['selected_name'] = c.get('productName','')
                vars['route'] = 'balance'
            else:
                vars['stage'] = 'select'
                vars['utterance'] = selection_prompt(cards)
                vars['route'] = 'dialogue'
        elif op == 'cards_balance':
            today = datetime.datetime.fromisoformat(str(vars['now'])).date()
            issued = str(data.get('statementDate') or '')
            due = str(data.get('lastPayDate') or '')
            next_cut = str(data.get('nextStatementDate') or '')
            cut_today = any(s and date_value(s) == today for s in [issued, next_cut])
            overdue = bool(due and date_value(due) < today)
            no_statement = not issued
            no_debt = data.get('statementPaymentStatus') == 'NO_DEBT'
            mode = 'new' if no_statement and not cut_today else ('cut' if cut_today else ('clear' if no_debt else ('overdue' if overdue else 'normal')))
            vars['issued_statement_date'] = issued
            vars['balance_mode'] = mode
            vars['balance_json'] = json.dumps(data, ensure_ascii=False)
            vars['available_currencies_json'] = json.dumps([code for code in ['TL','USD','EUR','GBP'] if data.get('debt' + code)])
            lines = []
            short = dict()
            opening = intro()
            if due:
                short['due'] = 'Borçlarınız için son ödeme tarihiniz bugündür.' if date_value(due) == today else ('Son ödeme tarihiniz ' + date_speech(due) + ' tarihinde geçmiştir.' if overdue else 'Borçlarınız için son ödeme tarihiniz ' + date_speech(due) + "'dir.")
            if mode == 'new':
                lines.append(opening + 'kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
                if next_cut: lines.append('İlk hesap kesim tarihiniz ' + date_speech(next_cut) + ' olacak.')
            elif mode == 'clear':
                lines.append(opening + 'kartınızın ' + date_speech(issued) + ' tarihli ekstresinden borcunuz bulunmamaktadır.')
                tl = data.get('debtTL')
                if tl and 'totalDebt' in tl:
                    if tl['totalDebt'] >= 0: lines.append('Gelecek dönemler dahil toplam borcunuz ' + money(tl['totalDebt'], 'Türk Lirası') + "'dir.")
                    else: lines.append('Türk Lirası borcunuz bulunmamaktadır.')
                if due: lines.append(short['due'] if overdue or date_value(due) == today else 'Son ödeme tarihiniz ' + date_speech(due) + ' olacaktır.')
            else:
                if mode == 'cut':
                    lines.append(opening + 'kartınız için bilgiler: Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
                elif mode == 'overdue':
                    lines.append(opening + 'kartınızın son ödeme tarihi geçmiştir.')
                transfer = []
                for currency, label in [('USD','Dolar'),('EUR','Euro'),('GBP','İngiliz Sterlini')]:
                    block = data.get('debt'+currency)
                    if block and block.get('transferAmount',0) > 0: transfer.append(label)
                if transfer: lines.append(' ve '.join(transfer) + ' borcunuzdan Türk Lirası borcunuza aktarım yapılmıştır.')
                clear = []
                readings = []
                for currency, label in [('TL','Türk Lirası'),('USD','Dolar'),('EUR','Euro'),('GBP','İngiliz Sterlini')]:
                    block = data.get('debt'+currency)
                    if not block: continue
                    field = 'remainingDebt' if mode == 'normal' else 'totalDebt'
                    amount = block[field]
                    if amount <= 0:
                        clear.append(label)
                        continue
                    if mode != 'normal':
                        line = label + ' toplam borcunuz ' + money(amount,label) + "'dir."
                    else:
                        debt = money(block['statementDebt'],label)
                        minimum = money(block['minPayment'],label)
                        remaining = money(block['remainingDebt'],label)
                        short[currency + '_minimum'] = 'Ödenmesi gereken minimum tutar ' + minimum + "'dir."
                        short[currency + '_debt'] = label + ' borcunuz ' + debt + "'dir."
                        if currency != 'TL':
                            line = label + ' borcunuz ' + debt + ', kalan toplam borcunuz ' + remaining + ', ödenmesi gereken minimum tutar ' + minimum + "'dir."
                        elif block['remainingMinPayment'] <= 0:
                            line = label + ' borcunuz ' + debt + ', kalan toplam borcunuz ' + remaining + "'dir. Minimum ödemenizi yaptığınız için teşekkür ederiz."
                        elif block['remainingMinPayment'] >= block['minPayment']:
                            line = label + ' borcunuz ' + debt + ', ödenmesi gereken minimum tutar ' + minimum + "'dir."
                        else:
                            line = label + ' borcunuz ' + debt + ', ödenmesi gereken minimum tutar ' + minimum + ', kalan toplam borcunuz ' + remaining + ', kalan minimum ödeme tutarınız ' + money(block['remainingMinPayment'],label) + "'dir."
                    readings.append(line)
                if mode == 'normal' and readings:
                    readings[0] = opening + 'kartınıza ait ' + date_speech(issued) + ' tarihinde kesilen ekstre ' + readings[0]
                lines.extend(readings)
                if clear:
                    names = clear[0] if len(clear) == 1 else ', '.join(clear[:-1]) + ' ve ' + clear[-1]
                    lines.append(names + ' borcunuz bulunmamaktadır.')
                tl = data.get('debtTL')
                if overdue and data.get('automaticPaymentFlag') == 'Y' and tl and tl.get('remainAutomaticPaymentAmount',0) > 0:
                    lines.append('Alınmayı bekleyen otomatik ödeme tutarınız ' + money(tl['remainAutomaticPaymentAmount'],'Türk Lirası') + "'dir.")
                if due: lines.append(short['due'])
            focus = str(vars.get('focus',''))
            if focus:
                currency = str(vars.get('selected_currency',''))
                key = 'due' if focus == 'due' else currency + '_' + focus
                if key in short: lines = [opening + 'kartınız için: ' + short[key]]
                else: lines = [opening + 'kartınız için istediğiniz bilgi bu yanıtta bulunmuyor.']
            vars['reading'] = ' '.join(lines)
            seen = json.loads(vars.get('seen_json','[]'))
            if vars['selected_card_number'] not in seen: seen.append(vars['selected_card_number'])
            vars['seen_json'] = json.dumps(seen)
            cards = json.loads(vars['cards_json'])
            remaining_cards = [c for c in cards if c['cardNumber'] not in seen]
            if remaining_cards and not focus and vars.get('pending') != 'email':
                vars['stage'] = 'another'
                vars['utterance'] = vars['reading'] + ' Başka bir kartınızın borcunu öğrenmek ister misiniz?'
                vars['route'] = 'dialogue'
            elif mode in ['new','clear'] and vars.get('pending') != 'email' and not focus:
                vars['route'] = 'clear_end'
            else:
                vars['reading_pending'] = vars['reading']
                vars['route'] = 'email_lookup'
        elif op == 'contact_email_get':
            address = str(data.get('ibanEmail') or '')
            if data.get('communicationType') == 'Phone': address = ''
            vars['registered_email'] = address
            vars['spoken_email'] = str(data.get('ttsEmail') or address) if address else ''
            prefix = str(vars.get('reading_pending',''))
            vars['reading_pending'] = ''
            if vars.get('pending') == 'email':
                vars['pending'] = ''
                if not address:
                    vars['stage'] = 'offer'
                    vars['utterance'] = prefix + ' Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.'
                elif not vars.get('issued_statement_date'):
                    vars['stage'] = 'finish'
                    vars['utterance'] = prefix + ' Kartınızın henüz kesilmiş bir ekstresi olmadığı için gönderebileceğim bir ekstre bulunmuyor.'
                else:
                    available = json.loads(vars['available_currencies_json'])
                    currency = vars.get('selected_currency','')
                    if currency not in available:
                        if len(available) == 1: vars['selected_currency'] = available[0]
                        else:
                            vars['stage'] = 'email_currency'
                            labels = dict(TL='Türk Lirası',USD='Dolar',EUR='Euro',GBP='İngiliz Sterlini')
                            vars['utterance'] = prefix + ' Hangi para birimine ait ekstrenizi göndermemi istersiniz? ' + ', '.join(labels[x] for x in available) + '.'
                    if vars.get('selected_currency') in available:
                        vars['stage'] = 'email_confirm'
                        vars['utterance'] = prefix + ' Ekstrenizi ' + vars['spoken_email'] + ' adresine göndermemi ister misiniz?'
                        vars['email_binding'] = '|'.join(str(vars.get(k,'')) for k in ['selected_card_number','issued_statement_date','registered_email','selected_currency'])
            else:
                vars['stage'] = 'offer'
                vars['utterance'] = prefix + (' Ekstrenizi kayıtlı mail adresinize gönderebilirim.' if address else '')
                if not address and not prefix:
                    vars['stage'] = 'finish'
                    vars['utterance'] = 'Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.'
            vars['route'] = 'dialogue'
        elif op == 'statement_week_get':
            week = int(data['statementWeek'])
            day = int(data['statementDay'])
            if week not in [1,2,3,4] or day not in range(1,32): raise ValueError('Invalid week')
            vars['current_statement_week'] = week
            vars['current_statement_day'] = day
            vars['relation_type'] = data.get('relationType','')
            vars['related_name'] = data.get('relatedCardProductName','')
            vars['related_card_number'] = data.get('relatedCardNumber','')
            ordinal = ['','birinci','ikinci','üçüncü','dördüncü']
            text = intro() + 'kartınızın hesap kesim tarihi her ayın ' + ordinal[week] + ' haftası olarak tanımlı.'
            related = str(data.get('relatedCardNumber') or '')
            if data.get('relationType') in ['M','C']:
                if not related or not related[-4:].isdigit(): raise ValueError('Missing joint card')
                digit_words = ['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
                text += ' Sonu ' + ' '.join(digit_words[int(x)] for x in related[-4:]) + ' ile biten ' + str(data.get('relatedCardProductName') or '') + ' kartınız da aynı ekstreyi paylaşır; hesap kesim haftası ve sonraki tarihler her iki kart için aynıdır.'
            text += ' Bir sonraki hesap kesim tarihiniz ' + date_speech(data['nextStatementDate']) + ', son ödeme tarihiniz ' + date_speech(data['nextLastPayDate']) + '. Hesap kesim tarihinizi değiştirmek ister misiniz?'
            vars['options_text'] = 'Hesap kesim tarihinizi ayın ' + ', '.join(ordinal[x] for x in [1,2,3,4] if x != week) + ' haftasına alabilirim. Hangisini tercih edersiniz?'
            vars['stage'] = 'week_start'
            vars['utterance'] = text
            vars['route'] = 'dialogue'
        elif op == 'statement_week_decide':
            if data.get('responseCode') != 0: raise ValueError('Preview refused')
            vars['preview_date'] = data['statementDate']
            vars['preview_due'] = data['statementDueDate']
            ordinal = ['','birinci','ikinci','üçüncü','dördüncü'][int(vars['selected_statement_week'])]
            text = 'Yeni hesap kesim haftanız her ayın ' + ordinal + ' haftası olacak. Yeni hesap kesim tarihiniz ' + date_speech(data['statementDate']) + ', son ödeme tarihiniz ' + date_speech(data['statementDueDate']) + ' olacak.'
            relation = vars.get('relation_type','')
            if relation == 'M': text += ' Bu değişiklik kartınıza bağlı ' + vars['related_name'] + ' kartınızı da etkileyecek.'
            elif relation == 'C': text += ' Bu değişiklik kartınızın bağlı olduğu ' + vars['related_name'] + ' kartınızı da etkileyecek.'
            text += ' Onaylıyor musunuz?'
            vars['preview_binding'] = vars['selected_card_number'] + ':' + str(vars['selected_statement_week'])
            vars['stage'] = 'week_confirm'
            vars['utterance'] = text
            vars['route'] = 'dialogue'
        elif op == 'statement_week_change':
            if data.get('responseCode') != 0 or data.get('exitState') != 'OK': raise ValueError('Change refused')
            if str(data.get('statementWeek','')) != str(vars['selected_statement_week']): raise ValueError('Week mismatch')
            changed = json.loads(vars.get('week_changed_json','[]'))
            changed.append(vars['selected_card_number'])
            if vars.get('related_card_number'): changed.append(vars['related_card_number'])
            vars['week_changed_json'] = json.dumps(changed)
            ordinal = ['','birinci','ikinci','üçüncü','dördüncü'][int(vars['selected_statement_week'])]
            vars['utterance'] = intro() + 'kartınızın hesap kesim haftası her ayın ' + ordinal + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + date_speech(vars['preview_date']) + ', son ödeme tarihiniz ' + date_speech(vars['preview_due']) + '.'
            vars['route'] = 'week_done'
        elif op == 'statement_pdf_send':
            if data.get('exitState') != 'DONE': raise ValueError('Send failed')
            vars['route'] = 'email_done'
        else: raise ValueError('Unknown operation')
    vars['event'] = ''
    vars['answer_name'] = ''
    vars['answer_digits'] = ''
    vars['answer_week'] = 0
    vars['answer_currency'] = ''
    vars['answer_focus'] = ''
    vars['commit_permission'] = ''
    vars['failed'] = 0
    vars['silences'] = 0
except Exception:
    vars['route'] = 'week_error' if str(vars.get('operation','')).startswith('statement_week') else 'service_error'
    vars['commit_permission'] = ''
    vars['utterance'] = ''
